-- Check if encounters has data for all patients with assessments
SELECT COUNT(DISTINCT e.pat_ref) as patients_with_encounters
FROM encounters e;

-- Check if all Intensive clinicians have a facility connection
SELECT COUNT(*) FROM clinicians c
WHERE c.care_coord = 'Intensive' AND c.fac_connect IS NULL;

-- Check how many assessments have symptom data
SELECT COUNT(*) FROM assessmentbasics ab
JOIN assessmentsymptomsandrisk asr ON ab.ab_key = asr.asr_key;

-- Check how many patients have assessments with symptom data
SELECT COUNT(DISTINCT ab.pat_owner_ref) FROM assessmentbasics ab
JOIN assessmentsymptomsandrisk asr ON ab.ab_key = asr.asr_key;

-- Check how many patients have no assessments
SELECT COUNT(*) FROM patients p
WHERE NOT EXISTS (SELECT 1 FROM assessmentbasics ab WHERE ab.pat_owner_ref = p.pat_key);

